<script setup lang="ts">
import {uiError,uiErrorMessage} from '../module-localization.ts';
import {uiMessage,joinMessages} from '../module-localization.ts';
import {localized} from '../module-localization.ts';
import {tr,messageRef,formatErrorCode} from '../../i18n/index.ts';
import {useWebSettings,settingsFields} from '../../state/web-settings.ts';
import ResearchUpload from '../../components/ResearchUpload.vue';
import AppIcon from '../../components/AppIcon.vue';
import PlotPlaceholder from '../../components/PlotPlaceholder.vue';
import {vTimePrecision} from '../../design/time-precision.ts';
import ModuleWorkbench from '../../components/ModuleWorkbench.vue';
import ModuleFrame from '../../components/ModuleFrame.vue';
import ModuleToolbar from '../../components/ModuleToolbar.vue';
import ModuleStatus from '../../components/ModuleStatus.vue';
import {ref,computed,onMounted,onUnmounted,markRaw,watchEffect,watch} from 'vue';
import type {ResearchContext,ResearchFile,JobView,ReconstructionConfig} from '../../platform/research.ts';
import {workspace} from '../../state/workspace.ts';
import {decodeWav} from '../../platform/decode.ts';
import {stop} from '../../state/audio.ts';
import WaveformViewport from '../../components/WaveformViewport.vue';
import {imageDimensions} from './image-header.ts';
import SpectralCanvas from './SpectralCanvas.vue';
import {resultConfigMatches} from './result-config.ts';
import {reconstructionErrorMessage,reconstructionErrorLabels as errors} from './error-messages.ts';
import type {ReconstructionPreview} from '../../platform/research.ts';
const props=defineProps<{context:ResearchContext;stateKey:string;active?:boolean}>();
const emit=defineEmits<{references:[];help:[];close:[]}>();
const wave=workspace(props.stateKey),files=ref<ResearchFile[]>([]),source=ref<ResearchFile>(),jobs=ref<JobView[]>([]),current=ref<JobView>();
const error=messageRef(''),notice=messageRef(''),busy=ref(false),imageUrl=ref(''),calibrated=ref(''),rebuilt=ref(''),metadata=ref<Record<string,unknown>>(),directory=ref(''),picker=ref<HTMLInputElement>();
const corners=ref<{x:number;y:number}[]>([]),selecting=ref(false),dimensions=ref({width:0,height:0});
const defaults:ReconstructionConfig={mode:'image',invert_image:false,vocoder:'none',algorithm:'griffin_lim',reconstruction_profile:'legacy',inference_device:'auto',phase_initialization:'auto',frequency_axis:'linear',auto_parameters:false,channel:0,audio_fft:1024,dynamic_range:60,strokes:[],time_start:0,time_end:1,freq_start:0,freq_end:11025,min_db:-30,max_db:0,win_length_ms:10,n_iter:32,target_sr:0,seed:0,corners:null};
const config=ref<ReconstructionConfig>({...defaults,reconstruction_profile:'calibrated',phase_initialization:'auto',inference_device:'auto'});
const durationInput=ref<number|string>(''),freqStartInput=ref<number|string>(0),freqEndInput=ref<number|string>('');
const calibrationReady=computed(()=>String(durationInput.value).trim()!==''&&String(freqStartInput.value).trim()!==''&&String(freqEndInput.value).trim()!==''&&Number.isFinite(Number(durationInput.value))&&Number(durationInput.value)>0&&Number(durationInput.value)<=30&&Number(freqStartInput.value)>=0&&Number(freqStartInput.value)<Number(freqEndInput.value)&&Number(freqEndInput.value)<=48000&&(config.value.frequency_axis!=='log'||Number(freqStartInput.value)>0));
watch([durationInput,freqStartInput,freqEndInput,()=>config.value.frequency_axis],()=>{if(calibrationReady.value){config.value.time_start=0;config.value.time_end=Number(durationInput.value);config.value.freq_start=Number(freqStartInput.value);config.value.freq_end=Number(freqEndInput.value);}});
const vocoder=ref<Awaited<ReturnType<NonNullable<NonNullable<ResearchContext['files']['tasks']>['vocoderStatus']>>>>(),downloadingVocoder=ref(false);
const componentStages:Record<string,string>=localized(()=>({idle:tr('modules.spectrogram-to-audio.not_downloaded'),downloading:tr('modules.spectrogram-to-audio.downloading'),verifying:tr('modules.spectrogram-to-audio.verifying'),extracting:tr('modules.spectrogram-to-audio.installing'),checking:tr('modules.spectrogram-to-audio.check_components'),complete:tr('modules.spectrogram-to-audio.downloaded_and_ready'),failed:tr('modules.spectrogram-to-audio.download_incomplete_retry_available')}));
const predicting=ref(false),prediction=ref<Record<string,number|string>>(),parametersEdited=ref(false);
const neural=computed(()=>config.value.algorithm==='neural_pipeline');
const pythonGrant=ref<{id:string;name:string}>(),checkingPython=ref(false),pythonNotice=messageRef('');
async function choosePython(){try{const selected=await props.context.files.tasks?.chooseInferencePython?.();if(selected){pythonGrant.value=selected;pythonNotice.value=uiMessage('modules.spectrogram-to-audio.environment_selected_check_compatibility');}}catch(e){pythonNotice.value=uiErrorMessage(e);}}
async function checkPython(){if(!pythonGrant.value||!props.context.files.tasks?.checkInferencePython)return;checkingPython.value=true;pythonNotice.value=uiMessage('modules.spectrogram-to-audio.checking_cuda_and_model_compatibility');try{const result=await props.context.files.tasks.checkInferencePython(pythonGrant.value.id);vocoder.value=await props.context.files.tasks.vocoderStatus?.();pythonNotice.value=uiMessage('modules.spectrogram-to-audio.check_passed_value_is_available',{v0:(result.gpu_name??'GPU')});config.value.inference_device='cuda';}catch(e){pythonNotice.value=uiErrorMessage(e);}finally{checkingPython.value=false;}}
function selectAlgorithm(){config.value.vocoder='none';config.value.inference_device='auto';if(neural.value)config.value.n_iter=32;}
watch(()=>config.value.vocoder,value=>{if(value==='bigvgan')config.value.n_iter=32;else if(!neural.value)config.value.inference_device='auto';});
const componentMessage=computed(()=>{if(props.context.files.kind==='server')return tr('modules.spectrogram-to-audio.the_web_app_uses_server_side_griffin_lim_reconstruction');if(neural.value&&vocoder.value&&!vocoder.value.pipeline_ready&&!vocoder.value.pipeline_available)return tr('modules.spectrogram-to-audio.spectral_restoration_and_vocoder_downloads_are_not_yet_released');if(vocoder.value?.ready&&(!neural.value||vocoder.value.pipeline_ready))return tr('modules.spectrogram-to-audio.downloaded_available_offline');const p=vocoder.value?.progress;if(p&&p.stage!=='idle')return `${componentStages[p.stage]??tr('modules.spectrogram-to-audio.processing')}${p.total>0?' · '+Math.floor(p.completed/p.total*100)+'%':''}`;return vocoder.value?.available?tr('modules.spectrogram-to-audio.not_downloaded_approximately_value_mb',{v0:(((neural.value?(vocoder.value.pipeline_download_bytes??vocoder.value.download_bytes):vocoder.value.download_bytes)/1e6).toFixed(1))}):vocoder.value?tr('modules.spectrogram-to-audio.component_download_not_yet_released'):tr('modules.spectrogram-to-audio.checking_component_status');});
let componentPolling=false;
async function refreshVocoder(){if(componentPolling||disposed||!props.context.files.tasks?.vocoderStatus)return;componentPolling=true;try{const value=await props.context.files.tasks.vocoderStatus();if(!disposed)vocoder.value=value;}catch{if(!disposed)notice.value=uiMessage('modules.spectrogram-to-audio.failed_to_read_vocoder_status_reopen_the_page_to');}finally{componentPolling=false;}}
async function downloadVocoder(){if(!props.context.files.tasks?.downloadVocoder||downloadingVocoder.value)return;downloadingVocoder.value=true;error.value='';try{await props.context.files.tasks.downloadVocoder();await refreshVocoder();if(!disposed)notice.value=uiMessage('modules.spectrogram-to-audio.reconstruction_components_downloaded_available_offline');}catch{if(!disposed)error.value=uiMessage('modules.spectrogram-to-audio.vocoder_download_or_verification_is_incomplete_check_network_and');}finally{downloadingVocoder.value=false;}}
type Mode='image'|'image_draw'|'audio_draw';
type Stroke=NonNullable<ReconstructionConfig['strokes']>[number];
const mode=ref<Mode>('image'),audioSource=ref<ResearchFile>(),audioFiles=ref<ResearchFile[]>([]),audioDirectory=ref('');
const imagePreview=ref<ReconstructionPreview>(),audioPreview=ref<ReconstructionPreview>(),imageStrokes=ref<Stroke[]>([]),audioStrokes=ref<Stroke[]>([]),imageKey=ref(''),audioKey=ref(''),channel=ref(0),audioFft=ref<512|1024|2048>(1024);
const audioFrequencyMax=ref(5000),audioCanvasHeight=ref(320);
function clampAudioFrequency(){audioFrequencyMax.value=Math.max(1,Math.min((audioPreview.value?.sample_rate??16000)/2,Number(audioFrequencyMax.value)||5000));}
watch(()=>audioPreview.value?.sample_rate,value=>{if(value)clampAudioFrequency();});
const submittedImage=ref(''),submittedAudio=ref('');
function drawingKey(audio:boolean){return JSON.stringify([audio?audioKey.value:imageKey.value,audio?audioStrokes.value:imageStrokes.value]);}
watchEffect(()=>{wave.dirty=(imageStrokes.value.length>0&&drawingKey(false)!==submittedImage.value)||(audioStrokes.value.length>0&&drawingKey(true)!==submittedAudio.value);});
const selectedSource=computed(()=>mode.value==='audio_draw'?audioSource.value:source.value);
const editorPreview=computed(()=>mode.value==='audio_draw'?audioPreview.value:imagePreview.value);
const strokes=computed({get:()=>mode.value==='audio_draw'?audioStrokes.value:imageStrokes.value,set:(value:Stroke[])=>{if(mode.value==='audio_draw')audioStrokes.value=value;else imageStrokes.value=value;}});
function imageSignature(){return JSON.stringify([source.value?.id,corners.value,config.value.invert_image]);}
function audioSignature(){return JSON.stringify([audioSource.value?.id,channel.value,audioFft.value]);}
const editorReady=computed(()=>mode.value==='audio_draw'?!!audioPreview.value&&audioKey.value===audioSignature():!!imagePreview.value&&imageKey.value===imageSignature());
const canSubmit=computed(()=>(mode.value==='audio_draw'||calibrationReady.value)&&!!selectedSource.value&&!!tasks.value?.reconstruct&&!busy.value&&!predicting.value&&!checkingPython.value&&(mode.value==='audio_draw'||(Number.isInteger(config.value.n_iter)&&config.value.n_iter>=1&&config.value.n_iter<=256&&config.value.win_length_ms>0&&config.value.win_length_ms<=160&&config.value.min_db<config.value.max_db))&&(mode.value==='image'||editorReady.value)&&(mode.value==='audio_draw'||!neural.value||vocoder.value?.pipeline_ready===true)&&(mode.value==='audio_draw'||config.value.vocoder!=='bigvgan'||vocoder.value?.ready===true)&&(mode.value==='audio_draw'||config.value.inference_device!=='cuda'||vocoder.value?.gpu_ready===true));
let predictionEpoch=0,predictionInFlight=false;
function useManualParameters(){
 config.value.auto_parameters=false;parametersEdited.value=true;
 predictionEpoch++;
}
async function predictParameters(){
 if(disposed||!calibrationReady.value||!source.value||!tasks.value?.reconstructionPreview||mode.value==='audio_draw'||predictionInFlight)return;
 const ticket=++predictionEpoch;predictionInFlight=true;predicting.value=true;error.value='';
 try{const result=await tasks.value.reconstructionPreview(source.value,{...snapshot(false),auto_parameters:true});
  if(disposed||ticket!==predictionEpoch)return;
  const values=result.prediction as Record<string,number|string>|undefined;
  if(values){prediction.value=values;config.value.win_length_ms=Number(values.win_length_ms);config.value.min_db=Number(values.min_db);config.value.max_db=Number(values.max_db);parametersEdited.value=false;}
 }catch(e){if(!disposed&&ticket===predictionEpoch){error.value=reconstructionErrorMessage(e);}}
 finally{predictionInFlight=false;predicting.value=false;}
}
watch(()=>JSON.stringify([durationInput.value,freqStartInput.value,freqEndInput.value,config.value.frequency_axis,config.value.invert_image,source.value?.id,JSON.stringify(corners.value),mode.value]),()=>{
 predictionEpoch++;prediction.value=undefined;parametersEdited.value=false;
});
function snapshot(includeStrokes=true):ReconstructionConfig{return mode.value==='audio_draw'?{...defaults,mode:'audio_draw',channel:channel.value,audio_fft:audioFft.value,dynamic_range:60,strokes:includeStrokes?audioStrokes.value.map(s=>({...s,points:s.points.map(p=>({...p}))})):[],corners:null}:{...config.value,mode:mode.value,strokes:mode.value==='image_draw'&&includeStrokes?imageStrokes.value.map(s=>({...s,points:s.points.map(p=>({...p}))})):[],corners:corners.value.length===4?corners.value.map(p=>({...p})):null};}
function switchMode(value:Mode){if(busy.value||mode.value===value)return;mode.value=value;epoch++;current.value=undefined;clearResult();error.value='';notice.value='';}
async function prepareCanvas(){const file=selectedSource.value;if(!file||!tasks.value?.reconstructionPreview)return;const ticket=++epoch;busy.value=true;error.value='';try{if(mode.value!=='audio_draw'&&corners.value.length!==0&&corners.value.length!==4)throw uiError(uiMessage('modules.spectrogram-to-audio.complete_the_four_point_selection_or_reset_to_the'));const key=mode.value==='audio_draw'?audioSignature():imageSignature();const value=await tasks.value.reconstructionPreview(file,snapshot(false));if(disposed||ticket!==epoch)return;if(file.sha256&&value.source_sha256!==file.sha256)throw uiError(uiMessage('modules.spectrogram-to-audio.source_file_changed_load_it_again'));if(mode.value==='audio_draw'){audioPreview.value=value;audioKey.value=key;audioStrokes.value=[];}else{imagePreview.value=value;imageKey.value=key;imageStrokes.value=[];}notice.value=uiMessage('modules.spectrogram-to-audio.canvas_loaded_zoom_and_draw_then_generate_audio');}catch(e){if(ticket===epoch)error.value=uiErrorMessage(e);}finally{if(ticket===epoch)busy.value=false;}}
async function loadAudio(file:ResearchFile){if(!file)return;audioSource.value=file;channel.value=0;audioPreview.value=undefined;audioStrokes.value=[];current.value=undefined;clearResult();}
watch(()=>mode.value==='audio_draw'?audioSignature():'',()=>{if(mode.value==='audio_draw'&&audioSource.value&&!editorReady.value)void prepareCanvas();});
async function chooseAudio(){try{const grant=await props.context.files.choose?.('input');if(grant){audioDirectory.value=grant.id;await refresh();}}catch(e){error.value=uiErrorMessage(e);}}
const tasks=computed(()=>props.context.files.tasks),running=computed(()=>jobs.value.some(j=>['queued','running','cancel_requested'].includes(j.state)));
const changed=computed(()=>{const frozen=metadata.value?.config as ReconstructionConfig|undefined;if(!frozen)return false;return !resultConfigMatches(snapshot(),frozen,defaults);});
const geometryNote=computed(()=>{const saved=metadata.value?.config as ReconstructionConfig|undefined;const shape=metadata.value?.image_shape as number[]|undefined;return saved?.corners?.length===4?tr('modules.spectrogram-to-audio.four_point_perspective_correction_applied_value',{v0:(shape?' · '+shape[1]+' × '+shape[0]:'')}):tr('modules.spectrogram-to-audio.using_full_image');});
const states:Record<string,string>=localized(()=>({queued:tr('modules.spectrogram-to-audio.queued'),running:tr('modules.spectrogram-to-audio.reconstructing'),cancel_requested:tr('modules.spectrogram-to-audio.cancelling'),cancelled:tr('modules.spectrogram-to-audio.cancelled'),failed:tr('modules.spectrogram-to-audio.failed'),interrupted:tr('modules.spectrogram-to-audio.interrupted_retry_available'),succeeded:tr('modules.spectrogram-to-audio.completed')}));
// Task rows render labels on demand; caught failures retain their descriptors.
let disposed=false,epoch=0,polling=false;const urls=new Set<string>();
function url(raw:ArrayBuffer,type:string){const value=URL.createObjectURL(new Blob([raw],{type}));urls.add(value);return value;}
function release(value:string){if(value){URL.revokeObjectURL(value);urls.delete(value);}}
function clearResult(){stop();wave.asset=null;metadata.value=undefined;release(calibrated.value);release(rebuilt.value);calibrated.value='';rebuilt.value='';}
async function refresh(){const selectedMode=mode.value;try{const list=await props.context.files.list((selectedMode==='audio_draw'?audioDirectory.value:directory.value)||undefined);if(!disposed&&mode.value===selectedMode){if(selectedMode==='audio_draw'){audioFiles.value=list.filter(f=>f.kind==='audio');if(audioFiles.value.length===1&&audioSource.value?.id!==audioFiles.value[0].id)await loadAudio(audioFiles.value[0]);}else files.value=list.filter(f=>f.kind==='image');}}catch(e){error.value=uiErrorMessage(e);}}
async function choose(){try{const grant=await props.context.files.choose?.('input');if(grant){directory.value=grant.id;await refresh();}}catch(e){error.value=uiErrorMessage(e);}}
async function load(file:ResearchFile){if(!file)return;const ticket=++epoch;current.value=undefined;error.value='';busy.value=true;try{if(file.size>16_000_000)throw uiError(uiMessage('modules.spectrogram-to-audio.images_are_limited_to_16_mb'));const data=await props.context.files.read(file);const size=imageDimensions(data.buffer);if(disposed||ticket!==epoch)return;dimensions.value=size;release(imageUrl.value);imageUrl.value=url(data.buffer,/\.png$/i.test(file.name)?'image/png':/\.bmp$/i.test(file.name)?'image/bmp':'image/jpeg');source.value=file;current.value=undefined;corners.value=[];selecting.value=false;config.value.invert_image=false;imagePreview.value=undefined;imageStrokes.value=[];clearResult();}catch(e){if(!disposed&&ticket===epoch)error.value=uiErrorMessage(e);}finally{if(ticket===epoch)busy.value=false;}}
async function capture(){try{const file=await props.context.files.capture?.();if(file){await load(file);if(source.value?.id===file.id){if(!files.value.some(f=>f.id===file.id))files.value.unshift(file);if(file.corners?.length===4){corners.value=file.corners.map(p=>({...p}));notice.value=uiMessage('modules.spectrogram-to-audio.screenshot_and_corners_loaded_reconstruct_directly_or_adjust_corners');}}}}catch(e){error.value=uiErrorMessage(e);}}
function pick(event:MouseEvent){if(!selecting.value||corners.value.length>=4)return;const rect=(event.currentTarget as Element).getBoundingClientRect();corners.value.push({x:Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width)),y:Math.max(0,Math.min(1,(event.clientY-rect.top)/rect.height))});if(corners.value.length===4)selecting.value=false;}
async function poll(){if(polling||disposed||!tasks.value?.reconstructions)return;polling=true;try{const data=await tasks.value.reconstructions();if(disposed)return;jobs.value=data;if(current.value){const next=data.find(j=>j.id===current.value?.id);if(next){const completed=current.value.state!=='succeeded'&&next.state==='succeeded';current.value=next;if(completed)await show(next);}}}catch(e){if(!disposed)error.value=uiErrorMessage(e);}finally{polling=false;}}
async function submit(){if(!canSubmit.value||!selectedSource.value||!tasks.value?.reconstruct)return;busy.value=true;error.value='';notice.value='';try{if(mode.value!=='audio_draw'&&corners.value.length!==0&&corners.value.length!==4)throw uiError(uiMessage('modules.spectrogram-to-audio.complete_four_point_selection_or_reset_to_the_full'));const frozen=snapshot(),key=drawingKey(mode.value==='audio_draw');clearResult();current.value=await tasks.value.reconstruct(selectedSource.value,frozen,crypto.randomUUID());if(mode.value==='audio_draw')submittedAudio.value=key;else if(mode.value==='image_draw')submittedImage.value=key;await poll();}catch(e){error.value=uiErrorMessage(e);}finally{busy.value=false;}}
async function show(job:JobView){const ticket=++epoch;current.value=job;clearResult();if(job.state!=='succeeded'||job.result_manifest?.kind!=='managed_spec2wav_files'||!tasks.value?.result)return;busy.value=true;error.value='';try{const entries=job.result_manifest.files;const blobs:ArrayBuffer[]=[];for(const file of entries){blobs.push(await tasks.value.result(job.id,file.id,file.sha256));if(disposed||ticket!==epoch)return;}if(disposed||ticket!==epoch)return;for(let i=0;i<entries.length;i++){const name=entries[i].name,raw=blobs[i];if(name==='calibrated.png')calibrated.value=url(raw,'image/png');else if(name==='reconstructed.png')rebuilt.value=url(raw,'image/png');else if(name.endsWith('.json'))metadata.value=JSON.parse(new TextDecoder().decode(raw));else {const asset=await decodeWav(raw,name);if(disposed||ticket!==epoch)return;wave.asset=markRaw(asset);wave.start=0;wave.end=asset.duration;wave.offset=0;wave.zoom=1;wave.channel=0;}}}catch(e){error.value=uiErrorMessage(e);}finally{if(ticket===epoch)busy.value=false;}}
async function cancel(job:JobView){try{await tasks.value?.cancelJob?.(job.id);await poll();}catch(e){error.value=uiErrorMessage(e);}}
async function retry(job:JobView){try{current.value=await tasks.value!.retry(job.id,crypto.randomUUID());await poll();}catch(e){error.value=uiErrorMessage(e);}}
async function save(){const job=current.value;if(!job||job.state!=='succeeded')return;busy.value=true;error.value='';try{if(tasks.value?.saveJob){const grant=await props.context.files.choose?.('output');if(!grant)return;const result=await tasks.value.saveJob(job.id,grant.id);notice.value=uiMessage('modules.spectrogram-to-audio.saved_value_result_files_existing_files_with_different_contents',{v0:(result.count)});}}catch(e){error.value=uiErrorMessage(e);}finally{busy.value=false;}}
async function download(id:string,name:string){try{await tasks.value?.download?.(id,name);}catch(e){error.value=uiErrorMessage(e);}}
function addFiles(event:Event){props.context.files.add?.([...((event.target as HTMLInputElement).files??[])]);void refresh();}
function beforeClose(){if(wave.dirty){notice.value=uiMessage('modules.spectrogram-to-audio.drawing_has_not_generated_audio_yet_generate_audio_before');return false;}return true;}
defineExpose({save:beforeClose});
onMounted(()=>{if(props.context.files.kind!=='desktop')void refresh();void poll();void refreshVocoder();});
watch(()=>props.active,active=>{if(active===false)stop();else{void poll();void refreshVocoder();}});
const timer=setInterval(()=>{if(props.active!==false||jobs.value.some(j=>['queued','running','cancel_requested'].includes(j.state)))void poll();if(props.active!==false||downloadingVocoder.value)void refreshVocoder();},2000);
onUnmounted(()=>{disposed=true;epoch++;wave.dirty=false;clearInterval(timer);predictionEpoch++;stop();for(const value of urls)URL.revokeObjectURL(value);});
useWebSettings(props.stateKey,{...settingsFields(config,['invert_image','vocoder','algorithm','reconstruction_profile','inference_device','phase_initialization','frequency_axis','auto_parameters','dynamic_range','min_db','max_db','win_length_ms','n_iter','target_sr','seed']),durationInput,freqStartInput,freqEndInput,audioFft,channel,audioFrequencyMax,audioCanvasHeight});
</script>
<template><ModuleFrame unified fit :aria-busy="busy" :label="tr('modules.spectrogram-to-audio.spectrogram_to_audio_workspace')" class="workspace-page m09-page">
<template #toolbar><ModuleToolbar><ResearchUpload :files="context.files" accept=".png,.jpg,.jpeg,.bmp,.wav,.mp3,.flac" @uploaded="refresh"/><div class="mode-switch" role="group" :aria-label="tr('modules.spectrogram-to-audio.reconstruction_mode')"><button :aria-pressed="mode==='image'" @click="switchMode('image')" :disabled="busy">{{tr('modules.spectrogram-to-audio.image_reconstruction')}}</button><button :aria-pressed="mode==='image_draw'" @click="switchMode('image_draw')" :disabled="busy">{{tr('modules.spectrogram-to-audio.drawn_image_reconstruction')}}</button><button :aria-pressed="mode==='audio_draw'" @click="switchMode('audio_draw');if(context.files.kind!=='desktop')refresh()" :disabled="busy">{{tr('modules.spectrogram-to-audio.hide_information_in_audio')}}</button></div><button class="primary" v-if="context.files.choose" @click="mode==='audio_draw'?chooseAudio():choose()" :disabled="busy"><AppIcon name="folder"/>{{mode==='audio_draw'?tr('modules.spectrogram-to-audio.open_audio_folder'):tr('modules.spectrogram-to-audio.select_image_folder')}}</button><button class="primary" v-if="context.files.capture&&mode!=='audio_draw'" @click="capture" :disabled="busy">{{tr('modules.spectrogram-to-audio.capture_screen')}}</button><template v-if="context.files.add"><input ref="picker" type="file" :accept="mode==='audio_draw'?'.wav,.mp3,.flac':'image/png,image/jpeg,image/bmp'" hidden multiple @change="addFiles"/><button class="primary" @click="picker?.click()">{{mode==='audio_draw'?tr('modules.spectrogram-to-audio.import_audio'):tr('modules.spectrogram-to-audio.import_image')}}</button></template><button v-if="directory||audioDirectory||context.files.kind==='server'" @click="refresh" :disabled="busy">{{tr('modules.spectrogram-to-audio.refresh_list')}}</button><template #actions><button type="button" data-action="module-help" @click="emit('help')">{{tr('modules.spectrogram-to-audio.help')}}</button><button @click="emit('references')"><AppIcon name="book"/>{{tr('modules.spectrogram-to-audio.methods_and_references')}}</button></template></ModuleToolbar></template>
