<div v-if="neural||config.vocoder==='bigvgan'" class="vocoder-settings"><label>{{tr('modules.spectrogram-to-audio.model_inference_device')}}<select :aria-label="tr('modules.spectrogram-to-audio.model_inference_device')" v-model="config.inference_device"><option value="auto">{{tr('modules.spectrogram-to-audio.auto_prefer_checked_gpu_environment')}}</option><option value="cpu">CPU</option><option value="cuda" :disabled="!vocoder?.gpu_ready">GPU（CUDA）</option></select></label><p v-if="config.inference_device==='cpu'||(config.inference_device==='auto'&&!vocoder?.gpu_ready)" class="muted">{{tr('modules.spectrogram-to-audio.cpu_inference_may_be_slow_for_longer_audio_select')}}</p><template v-if="tasks?.chooseInferencePython"><button @click="choosePython" :disabled="checkingPython">{{tr('modules.spectrogram-to-audio.select_existing_python_environment')}}</button><p v-if="pythonGrant" class="muted">{{pythonGrant.name}}</p><button @click="checkPython" :disabled="!pythonGrant||checkingPython">{{checkingPython?tr('modules.spectrogram-to-audio.checking_compatibility'):tr('modules.spectrogram-to-audio.check_compatibility')}}</button><p role="status" class="muted">{{pythonNotice||(vocoder?.gpu_ready?tr('modules.spectrogram-to-audio.available_value_value',{v0:(vocoder.gpu_name),v1:(vocoder.python_name)}):tr('modules.spectrogram-to-audio.select_python_exe_with_gpu_enabled_pytorch_installed_gpu'))}}</p></template><p class="muted">{{tr('modules.spectrogram-to-audio.gpu_environment_reuses_an_existing_installation_models_still_require')}}</p></div>
