wave.asset" :state="wave" compact-overview auto-amplitude continuous-detail/><p class="muted">{{tr('modules.spectrogram-to-audio.use_the_shared_playback_bar_below_for_the_full')}}</p></section><template #right><button class="primary" @click="submit" :disabled="!canSubmit">{{mode==='audio_draw'?tr('modules.spectrogram-to-audio.generate_hidden_information_audio'):mode==='image_draw'?tr('modules.spectrogram-to-audio.generate_drawn_audio'):tr('modules.spectrogram-to-audio.start_reconstruction')}}</button><p class="notice">{{mode==='audio_draw'?tr('modules.spectrogram-to-audio.edits_magnitudes_while_preserving_original_phase_then_generates_audio'):(neural?tr('modules.spectrogram-to-audio.after_gl_extracts_mel_spectra_restores_them_with_nafnet'):config.vocoder==='bigvgan'?tr('modules.spectrogram-to-audio.reconstructs_using_image_calibration_then_synthesizes_audio_with_bigvgan'):tr('modules.spectrogram-to-audio.enter_time_frequency_and_grayscale_calibration_from_the_image'))}}</p>
